from pathlib import Path
import os, subprocess, tempfile

tests = Path("tests/runtime")
evidence = Path(os.environ["WALK_OUTPUT"]).resolve()
evidence.mkdir(parents=True, exist_ok=True)
patch = '    async function exerciseFirstGuestAction(game, host, friend, phone) {\n        async function activate(control) {\n            await expect(control).toBeEnabled();\n            await expectUncoveredControl(control);\n            if (phone) await control.tap();\n            else await control.click();\n        }\n        if (game === \'chess\') {\n            await moveByKeyboard(host, \'e2\', \'ArrowUp\', 2);\n            await expect(friend.locator(\'[data-chess-status]\')).toHaveText(\'You’re Black · Your turn\');\n            for (const name of [\'e7\', \'e5\']) {\n                const square = friend.locator(\'[data-square=\' + name + \']\');\n                await expect(square).toBeInViewport({ ratio: 1 });\n                const box = await square.boundingBox();\n                const x = box.x + box.width / 2, y = box.y + box.height / 2;\n                assert.ok(await friend.locator(\'.arcade-chess #board\').evaluate((board, point) => {\n                    return board.contains(document.elementFromPoint(point.x, point.y));\n                }, { x, y }), \'the Chessground board receives the square pointer\');\n                if (phone) await friend.touchscreen.tap(x, y);\n                else await friend.mouse.click(x, y);\n            }\n            await expect(host.getByRole(\'button\', { name: \'e5, Black pawn\' })).toBeAttached();\n        } else if (game === \'crapeights\') {\n            await expect(host.locator(\'[data-eights-card]\')).toHaveCount(7);\n            if (await host.locator(\'[data-eights-action=draw]\').isEnabled()) {\n                await host.locator(\'[data-eights-action=draw]\').click();\n                await expect(host.locator(\'[data-eights-card]\')).toHaveCount(8);\n                const pass = host.locator(\'[data-eights-action=pass]\');\n                if (await pass.isVisible()) await pass.click();\n            }\n            await activate(friend.locator(\'[data-eights-action=draw]\'));\n            await expect(friend.locator(\'[data-eights-card]\')).toHaveCount(8);\n        } else if (game === \'turdrummy\') {\n            await activate(friend.locator(\'[data-rummy-action=draw-discard]\'));\n            await expect(friend.locator(\'[data-rummy-card]\')).toHaveCount(11);\n        } else if (game === \'turdspades\') {\n            await activate(friend.getByRole(\'button\', { name: \'Bid for me\' }));\n            await host.getByRole(\'button\', { name: \'Bid for me\' }).click();\n            await expect(friend.locator(\'[data-spades-table]\')).toHaveAttribute(\'data-phase\', \'play\');\n        } else if (game === \'turdjack\') {\n            await activate(friend.getByRole(\'button\', { name: \'Ready\', exact: true }));\n            await expect(host.locator(\'[data-jack-status]\')).toContainText(\'1/2 ready\');\n        } else if (game === \'turdtris\') {\n            await activate(friend.getByRole(\'button\', { name: \'Hard drop\' }));\n            await expect(friend.locator(\'[data-tris-match]\')).toHaveAttribute(\'data-sequence\', \'1\');\n            await expect(friend.locator(\'[data-tris-score]\')).toContainText(/· [1-9]\\d* pts/);\n        } else if (game === \'turdomania\') {\n            await expect(friend.locator(\'[data-mania-match]\')).toHaveAttribute(\'data-phase\', \'play\');\n            const board = friend.getByRole(\'grid\', { name: \'Your puzzle\' });\n            const layout = await board.getByRole(\'gridcell\').evaluateAll(nodes => {\n                const stacks = Array.from({ length: 6 }, () => []);\n                for (const { dataset } of nodes) {\n                    stacks[Number(dataset.col)][Number(dataset.row)] = { id: Number(dataset.maniaTile), kind: Number(dataset.kind) };\n                }\n                return stacks.filter(stack => stack.length);\n            });\n            const [first] = findDuelSolution(layout);\n            assert.notEqual(first, undefined);\n            const status = friend.locator(\'[data-mania-status]\');\n            const baseline = await board.locator(\'.mania-starter\').count() === 0;\n            const move = board.locator(\'[data-mania-tile="\' + first + \'"]\');\n            if (baseline) {\n                await expect(status).toHaveText(\'Pop matching groups of two or more.\');\n                await expect(board.locator(\'.mania-starter\')).toHaveCount(0);\n            } else {\n                await expect(status).toHaveText(\'Tap an outlined tile to pop its matching group.\');\n                await expect(move).toHaveClass(/mania-starter/);\n            }\n            await captureArcadeInvite(friend, friend.viewportSize(), \'matrix-turdomania-first-cue\');\n            await activate(move);\n            await expect(friend.locator(\'[data-mania-match]\')).toHaveAttribute(\'data-move\', \'1\');\n        } else if (game === \'turdrush\') {\n            await activate(friend.getByRole(\'button\', { name: \'Move left\' }));\n            await expect(friend.locator(\'[data-race-match]\')).toHaveAttribute(\'data-sequence\', \'1\');\n            await expect(friend.locator(\'[data-race-match]\')).toHaveAttribute(\'data-lane\', \'0\');\n        } else if (game === \'turdanoid\') {\n            await activate(friend.getByRole(\'button\', { name: \'Launch ball\' }));\n            await expect(friend.locator(\'[data-brick-match]\')).toHaveAttribute(\'data-sequence\', \'1\');\n            await expect(friend.locator(\'[data-brick-match]\')).toHaveAttribute(\'data-stuck\', \'false\');\n        }\n    }\n    async function verifyFreshInviteMatrix() {\n        const cases = [\n            [\'chess\', \'Royal Flush Chess\', \'Open Chess match\', \'[data-chess-status]\', /You’re Black · White to move/],\n            [\'crapeights\', \'Crappy Eights\', \'Open Eights table\', \'[data-eights-card]\', 7],\n            [\'turdrummy\', \'TurdRummy\', \'Open Rummy table\', \'[data-rummy-card]\', 10],\n            [\'turdspades\', \'TurdSpades\', \'Open 2-player Spades\', \'[data-spades-card]\', 13],\n            [\'turdjack\', \'Crapjack 21\', \'Open Crapjack table\', \'[data-jack-status]\', /2\\/4 seated · You’re Seat 2/],\n            [\'turdtris\', \'Turdtris Sprint\', \'Open Turdtris race\', \'[data-tris-match]\', \'[data-tris-controls]\'],\n            [\'turdomania\', \'Turdomania Duel\', \'Open Turdomania duel\', \'[data-mania-match]\', \'[role=grid][aria-label="Your puzzle"]\'],\n            [\'turdrush\', \'Turd Rush Race\', \'Open Turd Rush race\', \'[data-race-match]\', \'[data-race-controls]\'],\n            [\'turdanoid\', \'Turdanoid Brick Race\', \'Open Turdanoid race\', \'[data-brick-match]\', \'[data-brick-serve]\']\n        ];\n        let passed = 0;\n        const group = Number(process.env.ARCADE_MATRIX_GROUP);\n        for (const phone of [process.env.ARCADE_MATRIX_SIZE === \'phone\']) {\n            const viewport = phone ? { width: 390, height: 844 } : { width: 1440, height: 900 };\n            for (const [index, [game, label, open, target, seating]] of cases.entries()) {\n                if (Math.floor(index / 3) !== group || (process.env.ARCADE_ONLY_GAME && game !== process.env.ARCADE_ONLY_GAME)) continue;\n                const nick = \'MatrixHost\' + (phone ? \'P\' : \'D\') + String.fromCharCode(65 + index);\n                const description = [engine, viewport.width + \'x\' + viewport.height, game].join(\' \');\n                let host, friend, guestContext, stage = \'host\';\n                try {\n                    const brand = process.env.WALK_MATRIX_BRAND;\n                    const radDad = brand === \'rad-dad\';\n                    const hostContext = await browser.newContext({ viewport: { width: 1440, height: 900 },\n                        reducedMotion: \'reduce\', serviceWorkers: \'block\', ignoreHTTPSErrors: true });\n                    host = await hostContext.newPage();\n                    host.setDefaultTimeout(10000);\n                    await hostContext.route(\'**/*\', route => new URL(route.request().url()).origin === origin\n                        ? route.continue() : route.abort(\'blockedbyclient\'));\n                    host.on(\'pageerror\', error => errors.push(description + \': \' + error.message));\n                    const home = radDad ? \'/site/rad-dad/\' : \'/site/\';\n                    const startedAt = performance.now();\n                    await host.goto(origin + home);\n                    await host.getByRole(\'link\', { name: radDad ? /Hit the arcade/ : /^Arcade$/ }).first().click();\n                    assert.equal(new URL(host.url()).pathname, home + \'play/\');\n                    await host.getByRole(\'link\', { name: /Play online with friends/ }).click();\n                    await host.getByLabel(\'Invitation code\').fill(invitation);\n                    await host.getByRole(\'button\', { name: /Enter the community|Continue to Game Night/ }).click();\n                    await enterFromShell(host, nick, true);\n                    await host.getByRole(\'button\', { name: \'Start Game Night\', exact: true }).click();\n                    const picker = host.getByRole(\'combobox\', { name: \'Switch game\' });\n                    const hostActions = host.locator(\'[data-roombar]\');\n                    await expect(hostActions.getByRole(\'combobox\', { name: \'Switch game\' })).toHaveCount(1);\n                    const arcade = host.getByRole(\'button\', { name: /^Open (?:Stalemate|Rad Dad) Arcade$/ });\n                    const roomURL = host.url();\n                    await arcade.click();\n                    await expect(picker).toBeFocused();\n                    assert.equal(host.url(), roomURL);\n                    await expectUncoveredControl(picker);\n                    await expect(picker.locator(\'option[value=""]\')).toHaveText(\'Games\');\n                    await captureArcadeInvite(host, { width: 1440, height: 900 }, \'matrix-\' + game + \'-direct-choice\');\n                    await picker.focus();\n                    await picker.selectOption(game);\n                    console.log(\'HOST \' + description + \' \' + Math.round(performance.now() - startedAt) + \'ms\');\n                    const startGame = host.getByRole(\'button\', { name: open, exact: true });\n                    await expect(startGame).toBeVisible();\n                    await captureArcadeInvite(host, { width: 1440, height: 900 }, \'matrix-\' + game + \'-start\');\n                    const visible = await startGame.evaluate(button => {\n                        const box = button.getBoundingClientRect();\n                        return button.contains(document.elementFromPoint(box.x + box.width / 2, box.y + box.height / 2));\n                    });\n                    console.log(\'START \' + description + \' \' + visible);\n                    if (process.env.WALK_BEFORE === \'1\') await startGame.scrollIntoViewIfNeeded();\n                    else await expect(host.locator(\'details[open] > summary\').filter({ hasText: label })).toBeFocused();\n                    await expectUncoveredControl(startGame);\n                    await host.evaluate(() => {\n                        window.gameShares = 0;\n                        Object.defineProperty(navigator, \'share\', { configurable: true, value: async ({ url }) => {\n                            if (!navigator.userActivation.isActive) throw new DOMException(\'No activation\', \'NotAllowedError\');\n                            window.gameShares++;\n                            window.testGameInvitation = url;\n                        } });\n                    });\n                    await startGame.click();\n                    stage = \'share\';\n                    const invite = host.locator(\'details[open]\').getByRole(\'button\', { name: \'Invite a friend\', exact: true });\n                    await expectUncoveredControl(invite);\n                    await invite.click();\n                    const newGuest = host.getByRole(\'button\', { name: /^Invite a friend to / });\n                    await expect(newGuest).toBeFocused();\n                    await newGuest.click();\n                    const share = host.getByRole(\'button\', { name: \'Share invite\', exact: true });\n                    await expect(share).toBeFocused();\n                    assert.equal(await host.evaluate(() => window.gameShares), 0);\n                    await captureArcadeInvite(host, { width: 1440, height: 900 }, \'matrix-\' + game + \'-share\');\n                    await share.click();\n                    await expect(share).toBeHidden();\n                    await expect(invite).toBeFocused();\n                    console.log(\'SHARED \' + description + \' \' + Math.round(performance.now() - startedAt) + \'ms\');\n                    await captureArcadeInvite(host, { width: 1440, height: 900 }, \'matrix-\' + game + \'-shared\');\n                    const link = new URL(await host.evaluate(() => window.testGameInvitation));\n                    assert.equal(link.pathname, \'/beta/game-night/guest\');\n                    assert.equal(await host.evaluate(() => window.gameShares), 1);\n                    guestContext = await browser.newContext({ viewport, hasTouch: phone, reducedMotion: \'reduce\',\n                        serviceWorkers: \'block\', ignoreHTTPSErrors: true });\n                    await guestContext.route(\'**/*\', route => new URL(route.request().url()).origin === origin\n                        ? route.continue() : route.abort(\'blockedbyclient\'));\n                    friend = await guestContext.newPage();\n                    await friend.route(url => [\'/beta/game-night/invitation/details\', \'/beta/game-night/invitation/accept\', \'/beta/arcade-ticket\'].includes(url.pathname), async route => {\n                        await new Promise(resolve => setTimeout(resolve, 600));\n                        await route.continue();\n                    });\n                    friend.on(\'pageerror\', error => errors.push(description + \': \' + error.message));\n                    assert.equal((await guestContext.cookies()).length, 0);\n                    stage = \'accept\';\n                    const openedAt = performance.now();\n                    await tapGameNightLink(friend, link, phone);\n                    await expect(friend.getByRole(\'heading\', { name: label, exact: true })).toBeVisible();\n                    await expect(friend.getByText(nick + \' invited you to play.\', { exact: true })).toBeVisible();\n                    await expect(friend.getByRole(\'textbox\')).toHaveCount(0);\n                    await expect(friend.getByRole(\'button\')).toHaveCount(1);\n                    const join = friend.getByRole(\'button\', { name: \'Join game\', exact: true });\n                    await expect(join).toBeInViewport({ ratio: 1 });\n                    assert.ok((await join.boundingBox()).height >= 44);\n                    await captureArcadeInvite(friend, viewport, \'matrix-\' + game + \'-invite\');\n                    const inviteReadyAt = performance.now();\n                    await friend.waitForTimeout(2500);\n                    const acceptedAt = performance.now();\n                    await (phone ? join.tap() : join.click());\n                    stage = \'seat\';\n                    await expect(friend.locator(\'[data-game-night]\')).toBeVisible({ timeout: 12000 });\n                    await expect(friend.locator(\'details[open] > summary\').filter({ hasText: label })).toBeFocused();\n                    await expect(friend.getByLabel(\'Your nick\')).toBeHidden();\n                    await expect(friend.getByRole(\'combobox\', { name: \'Switch game\' })).toBeHidden();\n                    const ownView = friend.locator(target);\n                    if (typeof seating === \'number\') await expect(ownView).toHaveCount(seating);\n                    else if (seating instanceof RegExp) await expect(ownView).toHaveText(seating);\n                    else {\n                        await expect(ownView).toHaveAttribute(\'data-phase\', /^(countdown|play)$/);\n                        await expect(friend.locator(seating)).toBeVisible();\n                    }\n                    const seatedAt = performance.now();\n                    await captureArcadeInvite(friend, viewport, \'matrix-\' + game + \'-seated\');\n                    if (game === \'turdjack\') {\n                        await expect(host.locator(\'[data-jack-status]\')).toContainText(\'2/4 seated\');\n                        await host.getByRole(\'button\', { name: \'Start table\', exact: true }).click();\n                        await expect(friend.getByRole(\'button\', { name: \'Ready\', exact: true })).toBeVisible();\n                    }\n                    assert.ok(await host.evaluate(() => window.__lobby.active) === await friend.evaluate(() => window.__lobby.active));\n                    assert.ok(await friend.evaluate(() => document.documentElement.scrollWidth <= innerWidth));\n                    await expectUncoveredControl(friend.locator(\'[data-send]\'));\n                    stage = \'first play\';\n                    await exerciseFirstGuestAction(game, host, friend, phone);\n                    const firstPlayAt = performance.now();\n                    const elapsed = Math.round(firstPlayAt - openedAt);\n                    console.log(\'PHASES \' + description + \' \' + [inviteReadyAt - openedAt, seatedAt - acceptedAt, firstPlayAt - seatedAt, elapsed].map(Math.round).join(\' \'));\n                    console.log(\'TIME \' + description + \' \' + elapsed + \'ms\');\n                    await captureArcadeInvite(friend, viewport, \'matrix-\' + game + \'-first-play\');\n                    stage = \'leave\';\n                    await friend.locator(\'[data-leave]\').click();\n                    await expect(friend.locator(\'[data-game-night]\')).toBeHidden();\n                    await expect.poll(async () => (await guestContext.request.get(origin + \'/beta/state?game-guest=1\')).status()).toBe(401);\n                    console.log(\'PASS \' + description + \' one action to named handoff, exact seat, first play, and Leave\');\n                    passed++;\n                } catch (error) {\n                    const reason = String(error?.message || \'\').replace(/(?:https?:\\/\\/[^\\s<>"\']+|#[a-z-]+=[^\\s<>"\']+)/gi, \'[private value]\');\n                    if (friend && stage === \'seat\') {\n                        const known = [\'[data-guest-status]\', \'[data-game-guest-connecting] [role=status]\', \'[data-game-error]\'];\n                        const text = await friend.evaluate(selectors => selectors.map(selector => document.querySelector(selector)?.textContent?.trim().slice(0, 160)), known).catch(() => []);\n                        console.error(\'Seat status\', JSON.stringify(text).replace(/(?:https?:[^ ]+|[a-f0-9]{32,})/gi, \'[private value]\'));\n                    }\n                    console.error(\'FAIL \' + description + \' stage=\' + stage + \'\\n\' + reason);\n                } finally {\n                    if (guestContext) await guestContext.close();\n                    if (host) await host.context().close();\n                }\n            }\n        }\n        assert.equal(passed, process.env.ARCADE_ONLY_GAME ? 1 : 3, \'all exact game entries pass\');\n    }\n'
if os.environ.get("WALK_PACKAGED_ENTRANCES"):
    original_host_entry = """                    await hostContext.route('**/*', route => new URL(route.request().url()).origin === origin
                        ? route.continue() : route.abort('blockedbyclient'));
                    host.on('pageerror', error => errors.push(description + ': ' + error.message));
                    const home = radDad ? '/site/rad-dad/' : '/site/';
                    const startedAt = performance.now();
                    await host.goto(origin + home);
                    await host.getByRole('link', { name: radDad ? /Hit the arcade/ : /^Arcade$/ }).first().click();
                    assert.equal(new URL(host.url()).pathname, home + 'play/');
                    await host.getByRole('link', { name: /Play online with friends/ }).click();"""
    packaged_host_entry = """                    const { stat } = await import('node:fs/promises');
                    const { resolve, sep } = await import('node:path');
                    const home = radDad ? '/site/rad-dad/' : '/site/';
                    const arcadePath = home + 'play/';
                    const arcadeRoot = resolve(process.env.WALK_PACKAGED_ENTRANCES, brand, 'play');
                    let entryDestination;
                    await hostContext.route('**/*', async route => {
                        const url = new URL(route.request().url());
                        if (url.href === entryDestination?.href) {
                            const localEntry = origin + '/beta/?via=' + brand;
                            return route.fulfill({
                                status: 200,
                                contentType: 'text/html; charset=utf-8',
                                body: '<!doctype html><script>location.replace(' + JSON.stringify(localEntry) + ')</script>'
                            });
                        }
                        if (url.origin !== origin) return route.abort('blockedbyclient');
                        if (!url.pathname.startsWith(arcadePath)) return route.continue();
                        const name = decodeURIComponent(url.pathname.slice(arcadePath.length));
                        const file = resolve(arcadeRoot, name.endsWith('/') || !name ? name + 'index.html' : name);
                        if (!file.startsWith(arcadeRoot + sep)) return route.fulfill({ status: 404 });
                        const entry = await stat(file).catch(error => {
                            if (error.code !== 'ENOENT') throw error;
                        });
                        if (!entry?.isFile()) return route.fulfill({ status: 404 });
                        return route.fulfill({ path: file, headers: { 'cache-control': 'no-store' } });
                    });
                    host.on('pageerror', error => errors.push(description + ': ' + error.message));
                    const startedAt = performance.now();
                    await host.goto(origin + arcadePath);
                    const inviteEntry = host.getByRole('link', { name: /Play online with friends/ });
                    await expect(inviteEntry).toBeVisible();
                    entryDestination = new URL(await inviteEntry.getAttribute('href'));
                    assert.ok(['http:', 'https:'].includes(entryDestination.protocol));
                    assert.equal(entryDestination.hostname, '127.0.0.1');
                    assert.equal(entryDestination.pathname, '/beta/');
                    assert.equal(entryDestination.search, '?via=' + brand);
                    assert.ok(!entryDestination.username && !entryDestination.password && !entryDestination.hash);
                    if (entryDestination.origin === origin) entryDestination = undefined;
                    await inviteEntry.click();
                    await host.waitForURL(origin + '/beta/?via=' + brand);"""
    assert patch.count(original_host_entry) == 1
    patch = patch.replace(original_host_entry, packaged_host_entry)

with (
    tempfile.NamedTemporaryFile(mode="w", prefix=".game-night-matrix-browser-", suffix=".mjs", dir=tests) as browser,
    tempfile.NamedTemporaryFile(mode="w", prefix=".game-night-matrix-transport-", suffix=".mjs", dir=tests) as transport,
    tempfile.NamedTemporaryFile(mode="w", prefix=".game-night-matrix-preview-", suffix=".mjs", dir=tests) as preview,
):
    source = (tests / "arcade-browser.mjs").read_text()
    share = source.index('    async function shareGameNightLink(')
    before, after = source[:share], source[share:]
    line = "await host.getByRole('button', { name: 'Invite players' }).click();"
    after = after.replace(line, "await host.locator('details[open]').getByRole('button', { name: 'Invite a friend', exact: true }).click();", 1)
    source = before + after
    share_dispatch = "\n        if (options.webJamShare) {"
    assert source.count(share_dispatch) == 1
    dispatch_try = "\n    try {\n"
    dispatch = source.rindex(dispatch_try, 0, source.index(share_dispatch))
    run_matrix = "        await verifyFreshInviteMatrix();\n        assert.deepEqual(errors, []);\n        return;\n"
    browser.write(source[:dispatch] + "\n" + patch + dispatch_try + run_matrix + source[dispatch + len(dispatch_try):])
    browser.flush()
    # Use the Stalemate generator's via-only arcade link in the loopback mirror.
    preview_source = (tests / "arcade-preview-site.mjs").read_text()
    shortcut = 'href="${GAME_NIGHT}">Play online with friends →'
    assert preview_source.count(shortcut) == 1
    preview.write(preview_source.replace(shortcut, 'href="/beta/?via=stalemate">Play online with friends →'))
    preview.flush()
    harness = (tests / "arcade-transport.mjs").read_text()
    assert harness.count("'./arcade-browser.mjs'") == 1
    assert harness.count("'./arcade-preview-site.mjs'") == 1
    harness = harness.replace("'./arcade-browser.mjs'", "'./" + Path(browser.name).name + "'")
    harness = harness.replace("'./arcade-preview-site.mjs'", "'./" + Path(preview.name).name + "'")
    transport.write(harness)
    transport.flush()
    env = dict(os.environ, WALK_QT_DESTINATIONS=Path(os.environ["WALK_PICKER"]).read_text())
    ok = True
    for engine in os.environ.get("ARCADE_WALK_ENGINES", "chromium,webkit").split(","):
        summary = evidence / (os.environ.get("WALK_STAGE", "after") + "-" + engine + ".log")
        with summary.open("w") as out:
            for size in os.environ.get("ARCADE_WALK_SIZES", "phone,desktop").split(","):
                for group in map(int, os.environ.get("ARCADE_WALK_GROUPS", "0,1,2").split(",")):
                    run_env = dict(env, ARCADE_MATRIX_SIZE=size, ARCADE_MATRIX_GROUP=str(group))
                    with tempfile.TemporaryFile(mode="w+") as log:
                        status = subprocess.run(["node", transport.name, "--browser=" + engine], env=run_env, stdout=log, stderr=subprocess.STDOUT).returncode
                        log.seek(0)
                        result = log.read()
                    ok &= status == 0
                    for line in result.splitlines():
                        if line.startswith(("PASS ", "FAIL ", "TIME ", "START ", "PHASES ", "HOST ", "SHARED ")):
                            print(line[:155], flush=True)
                            print(line, file=out, flush=True)
                    if status:
                        with (evidence / (os.environ.get("WALK_STAGE", "after") + "-" + engine + "-" + size + "-" + str(group) + "-diagnostics.log")).open("w") as failure:
                            print(result, file=failure)
    raise SystemExit(0 if ok else 1)
